// Find the maximum element in an array
int findMax(int[] arr) {
    int max = arr[0]; // Initialization
    int i = 1;
    // Loop invariant: max is the largest element in arr[0..i-1]
    while (i < arr.length) {
        // Maintenance
        if (arr[i] > max) {
            max = arr[i];
        }
        i++;
    }
    // Termination: max is the largest element in the entire array
    return max;
}
